const e_ = joinWith('e');
// Articolo davanti al nome: «l’Orient Bambino», «l’Aachen 42», «il Turtle».
const voc = (m: string) => /^[aeiouhAEIOUH]/.test(m);
// «lo» delante de s + consonante, z, gn, ps, x e y: «lo Startimer».
const lo = (m: string) => /^(s[^aeiou]|z|gn|ps|x|y)/i.test(m);
const il = (m: string) => (voc(m) ? `l’${m}` : lo(m) ? `lo ${m}` : `il ${m}`);
const Il = (m: string) => (voc(m) ? `L’${m}` : lo(m) ? `Lo ${m}` : `Il ${m}`);
const del = (m: string) => (voc(m) ? `dell’${m}` : lo(m) ? `dello ${m}` : `del ${m}`);

